"""run_a, generated by PythFinder -- do not edit."""

from pybricks.tools import wait


def run(core):
    """Drive this run. The only thing runs.py needs to call."""
    # Team robot
    drive = core.configure(
        wheel_diameter=55.6, axle_track=160.1,
        straight_speed=200, straight_acceleration=400,
        turn_rate=150, turn_acceleration=300,
        use_gyro=True)
    core.set_heading(0)

    drive.straight(750)
    wait(600)
    core.turn_to(90, 90)
    drive.straight(300)
    core.turn_to(200.51, 110.51)
    drive.straight(856.3)
    core.turn_to(0, 159.49)
    core.turn_to(90, 90)
    drive.straight(300)
    core.turn_to(0, -90)
    drive.straight(300)

    core.stopTaskMotors()
